(()=>{'use strict';
const names=['Morning Soul','Sunset Lounge','Night Groove','Soft Motion'];
const audio=document.querySelector('#audio');
if(audio){let selected=0;const play=document.querySelector('#audio-play'),status=document.querySelector('#audio-status');audio.volume=.6;
const sync=()=>{play.innerHTML=window.airIcons[audio.paused?'play':'pause'];play.setAttribute('aria-label',audio.paused?'Воспроизвести':'Пауза');document.body.classList.toggle('is-playing',!audio.paused)};
const start=async()=>{status.textContent='Загрузка эскиза…';try{await audio.play();status.textContent='Играет инструментальный эскиз · повтор'}catch(e){status.textContent='Не удалось воспроизвести. Попробуйте ещё раз.'}sync()};
function choose(n){const resume=!audio.paused;audio.pause();selected=n;audio.src='/assets/preview-'+n+'.wav';document.querySelector('#track-title').textContent=names[n];document.querySelector('#track-genre').textContent=['SOUL / JAZZ · NICO','LOUNGE · SANDRA','FUNK / DISCO · LEO','AMBIENT · MIA'][n];document.querySelectorAll('[data-track]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.track===n));status.textContent='Выбрано: '+names[n]+'. Нажмите Play';sync();if(resume)start()}
document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>choose(+b.dataset.track));play.onclick=()=>{if(audio.paused)start();else{audio.pause();status.textContent='Пауза';sync()}};audio.addEventListener('error',()=>{status.textContent='Аудио недоступно. Выберите другое настроение.';sync()});audio.addEventListener('pause',sync);audio.addEventListener('playing',sync);document.querySelector('#audio-volume').oninput=e=>audio.volume=+e.target.value/100;document.querySelector('#previous-track').onclick=()=>choose((selected+3)%4);document.querySelector('#next-track').onclick=()=>choose((selected+1)%4);audio.addEventListener('timeupdate',()=>{document.querySelector('#elapsed').textContent=Math.floor(audio.currentTime/60)+':'+String(Math.floor(audio.currentTime%60)).padStart(2,'0')});const m=new URLSearchParams(location.search).get('mood');if(m!==null&&/^[0-3]$/.test(m))choose(+m);
}
const schedule=document.querySelector('#schedule');if(schedule){const defaults=[0,1,2,3];let values=defaults.slice();try{const v=JSON.parse(localStorage.getItem('promoair-schedule'));if(Array.isArray(v)&&v.length===4&&v.every(x=>Number.isInteger(x)&&x>=0&&x<4))values=v}catch{}const hours=['09:00','13:00','18:00','22:00'],notes=['Мягкое начало дня','Время встреч и разговоров','Вечер набирает ритм','Спокойное завершение'];function render(){schedule.replaceChildren();hours.forEach((time,i)=>{const row=document.createElement('div');row.className='schedule-row';row.innerHTML='<time>'+time+'</time><label>Настроение<select aria-label="Настроение в '+time+'">'+names.map((x,j)=>'<option value="'+j+'">'+x+'</option>').join('')+'</select></label><span>'+notes[i]+'</span>';const select=row.querySelector('select');select.value=values[i];select.onchange=()=>{values[i]=+select.value;save()};schedule.append(row)})}function save(){try{localStorage.setItem('promoair-schedule',JSON.stringify(values));document.querySelector('#schedule-status').textContent='Сохранено в этом браузере. Реальный эфир не изменён.'}catch{document.querySelector('#schedule-status').textContent='Изменения действуют до закрытия страницы.'}}render();document.querySelector('#reset-schedule').onclick=()=>{values=defaults.slice();render();save()}}
const brand=document.querySelector('#brand');if(brand)brand.oninput=()=>{document.querySelector('#brand-preview').textContent='Добро пожаловать'+(brand.value.trim()?' в «'+brand.value.trim()+'»':'')+'! Устраивайтесь поудобнее. Мы уже выбрали музыку для вашего дня.'};
const zv=document.querySelector('#zone-volume');if(zv){let active=0;const values=[40,55,35],zones=['Лобби','Ресторан','Терраса'],moods=['Soft Motion · спокойный приём гостей','Sunset Lounge · вкус долгого вечера','Morning Soul · воздух и лёгкость'];document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{active=+b.dataset.zone;document.querySelectorAll('[data-zone]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelector('#zone-name').textContent=zones[active];document.querySelector('#zone-mood').textContent=moods[active];zv.value=values[active];document.querySelector('#zone-value').textContent=values[active]+'%'});zv.oninput=()=>{values[active]=+zv.value;document.querySelector('#zone-value').textContent=zv.value+'%'}}
})();
